import csv,json,pathlib,re
root=pathlib.Path.cwd()
rows=list(csv.DictReader((root/'@prime/UI_MODULES.csv').open(encoding='utf-8',newline='')))
by_id={r['module_id']:r for r in rows}
assert len(rows)==len(by_id)==60, 'module identity/count changed'
phases=(root/'@prime/UI_PHASES.md').read_text(encoding='utf-8')
tasks=set(re.findall(r'^\| (UI\d+-\d+) \|',phases,re.M))
covered={t for r in rows for t in r['ui_tasks'].split(';') if t.startswith('UI')}
assert covered==tasks, ('task coverage',tasks-covered,covered-tasks)
for r in rows:
    if r['path_state']=='EXISTING': assert (root/r['path']).is_file(), r['path']
    for dep in filter(None,r['depends_on_modules'].split(';')): assert dep in by_id, (r['module_id'],dep)
    for source in filter(None,r['demo_sources'].split(';')): assert (root/source).exists(),source
    doc,anchor=r['plan_anchor'].split('#',1)
    text=(root/'@prime'/doc).read_text(encoding='utf-8')
    headings=re.findall(r'^#+ (.+)$',text,re.M)
    def slug(s): return re.sub(r'[^\w\- ]','',s.lower()).replace(' ','-')
    assert anchor in {slug(h) for h in headings},r['plan_anchor']
visiting=set();visited=set()
def visit(mid):
    assert mid not in visiting, ('cycle',mid)
    if mid in visited: return
    visiting.add(mid)
    for dep in filter(None,by_id[mid]['depends_on_modules'].split(';')): visit(dep)
    visiting.remove(mid);visited.add(mid)
for mid in by_id: visit(mid)
for name in ['mouse-repair-verification.md']:
    doc=root/'@prime/evidence/ui'/name
    for target in re.findall(r'\]\(([^)]+)\)',doc.read_text(encoding='utf-8')):
        if '://' not in target and not target.startswith('#'):
            assert (doc.parent/target.split('#')[0]).exists(),target
print(json.dumps({'modules':len(rows),'ui_tasks':len(tasks),'dependencies':'acyclic','existing_paths':'resolved','demo_sources':'resolved','plan_anchors':'resolved','current_evidence_links':'resolved'}))
